import type { ContentDetail, ContentKind, ContentSummary } from '$lib/types/content'

const capabilities = { copyText:true,copyImage:true,copyFile:true,copyPath:true,openUrl:true,revealSensitive:true,edit:true,save:false,unsave:true,delete:true,reorder:true }
export function fixtureSummary(id:string,kind:ContentKind,retention:'temporary'|'saved'):ContentSummary{return{id,kind,retention,title:id,preview:`${kind} preview`,createdAt:'2026-01-01T00:00:00Z',updatedAt:'2026-01-01T00:00:00Z',cleanupAt:retention==='temporary'?'2026-02-01T00:00:00Z':null,capabilities:{...capabilities,save:retention==='temporary',unsave:retention==='saved'}}}
export const allKindSummaries:ContentSummary[]=[fixtureSummary('dock:text','text','temporary'),fixtureSummary('dock:image','image','temporary'),fixtureSummary('dock:file','file','temporary'),fixtureSummary('vault:credential','credential','saved'),fixtureSummary('vault:bookmark','bookmark','saved'),fixtureSummary('vault:note','note','saved')]
export function fixtureDetail(item:ContentSummary):ContentDetail{switch(item.kind){case'text':return{kind:'text',summary:item as any,title:item.title,body:'fixture text'};case'image':return{kind:'image',summary:item as any,fileName:'image.png',assetPath:'fixture/image.png',mimeType:'image/png',width:100,height:100,available:true};case'file':return{kind:'file',summary:item as any,fileName:'file.pdf',assetPath:'fixture/file.pdf',mimeType:'application/pdf',sizeBytes:10,available:true};case'credential':return{kind:'credential',summary:item as any,fields:[{key:'user',value:'fixture-user',isSensitive:false,sortOrder:0},{key:'password',value:'dummy-secret',isSensitive:true,sortOrder:1}],notes:'fixture notes',tags:[]};case'bookmark':return{kind:'bookmark',summary:item as any,url:'https://example.invalid',fields:[],notes:null,tags:[]};case'note':return{kind:'note',summary:item as any,body:'fixture note',fields:[],tags:[]}}}
